#!/usr/bin/env python3
"""Validate tools/catalog.yaml and generate:
  tools/README.md            human-readable catalogue
  tools/mcp/<server>.json    MCP tool definitions (name, description, inputSchema, annotations)
  tools/catalog.json         machine-readable copy used by the Architecture Explorer

Usage: python3 tools/build_catalog.py [--check]
  --check  fail if generated files are out of date (for CI)
"""
import json, os, re, sys

import yaml

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
LEVELS = ["L0", "L1", "L2", "L3", "L4"]
RADIUS = ["none", "single-service", "multi-service", "platform"]
REQUIRED = ["name", "server", "category", "description", "mutating", "dry_run", "default_autonomy",
            "max_autonomy", "blast_radius", "inputs", "gcp", "aws", "gates"]


def validate(cat):
    errs = []
    servers = {s["id"] for s in cat["servers"]}
    names = set()
    for t in cat["tools"]:
        n = t.get("name", "?")
        for f in REQUIRED:
            if f not in t:
                errs.append(f"{n}: missing '{f}'")
        if n in names:
            errs.append(f"{n}: duplicate name")
        names.add(n)
        if t.get("server") not in servers:
            errs.append(f"{n}: unknown server '{t.get('server')}'")
        if t.get("category") not in ("read", "act", "workflow", "control"):
            errs.append(f"{n}: bad category")
        if t.get("blast_radius") not in RADIUS:
            errs.append(f"{n}: bad blast_radius")
        d, m = t.get("default_autonomy"), t.get("max_autonomy")
        if d not in LEVELS or m not in LEVELS or LEVELS.index(d) > LEVELS.index(m):
            errs.append(f"{n}: autonomy default {d} must be <= max {m}")
        if t.get("category") == "act" and "G9" not in t.get("gates", []):
            errs.append(f"{n}: act tools must pass G9 (action policy)")
        if t.get("approval") == "always" and LEVELS.index(m) > 2:
            errs.append(f"{n}: approval 'always' but max_autonomy above L2")
        if t.get("category") == "control" and m != "L0":
            errs.append(f"{n}: control tools are operator-only (max_autonomy L0)")
        if not re.fullmatch(r"[a-z0-9]+\.[a-z0-9_]+", n):
            errs.append(f"{n}: name must look like server_prefix.verb_object")
    # agent specs must only reference catalogued tools
    spec = os.path.join(ROOT, "templates", "agent-spec.yaml")
    if os.path.exists(spec):
        s = yaml.safe_load(open(spec))
        for tool in s.get("tools", []):
            if tool["name"] not in names:
                errs.append(f"templates/agent-spec.yaml references unknown tool {tool['name']}")
        for act in (s.get("autonomy", {}).get("actions") or {}):
            if act not in names:
                errs.append(f"templates/agent-spec.yaml autonomy references unknown tool {act}")
    return errs


def input_schema(inputs):
    props, req = {}, []
    for k, v in inputs.items():
        v = dict(v)
        opt = v.pop("optional", False)
        props[k] = v
        if not opt:
            req.append(k)
    return {"type": "object", "properties": props, "required": req, "additionalProperties": False}


def mcp_defs(cat):
    out = {}
    for t in cat["tools"]:
        out.setdefault(t["server"], []).append({
            "name": t["name"],
            "description": t["description"] + (" " + t["notes"] if t.get("notes") else ""),
            "inputSchema": input_schema(t["inputs"]),
            "annotations": {
                "title": t["name"],
                "readOnlyHint": not t["mutating"],
                "destructiveHint": t["mutating"] and t["blast_radius"] != "none",
                "idempotentHint": t["category"] in ("read",) or t["name"].startswith(("k8s.scale", "flags.set")),
                "openWorldHint": False,
            },
            "x-agentops": {k: t.get(k) for k in ("category", "dry_run", "default_autonomy", "max_autonomy",
                                                  "blast_radius", "approval", "gates", "gcp", "aws")},
        })
    return out


def readme(cat):
    servers = {s["id"]: s for s in cat["servers"]}
    L = ["# Tool catalogue", "",
         "<!-- Generated by tools/build_catalog.py from catalog.yaml. Edit the YAML, not this file. -->", "",
         "The tools layer (L6) is the only way agents change anything. Each server is an MCP server with its own "
         "least-privilege identity; agents hold no mutating credentials. Every call passes the model gateway, action "
         "policy (G9) and, where required, human approval (G10).", "",
         f"**{len(cat['tools'])} tools across {len(cat['servers'])} servers.** Machine-readable MCP definitions are in "
         "[`mcp/`](mcp/); the source of truth is [`catalog.yaml`](catalog.yaml).", "",
         "| Category | Meaning |", "| --- | --- |",
         "| read | No side effects; safe at L4 |",
         "| act | Changes a system; policy-gated, dry-run first where supported |",
         "| workflow | Records and communication (tickets, chat, approvals) |",
         "| control | Controls the agent platform itself; operators only, never agents |", "",
         "## At a glance", "",
         "| Tool | Server | Category | Mutating | Dry-run | Autonomy (start → max) | Blast radius | Approval |",
         "| --- | --- | --- | --- | --- | --- | --- | --- |"]
    for t in cat["tools"]:
        L.append(f"| [`{t['name']}`](#{t['name'].replace('.', '')}) | {servers[t['server']]['title']} | {t['category']} | "
                 f"{'yes' if t['mutating'] else 'no'} | {'yes' if t['dry_run'] else 'no'} | "
                 f"{t['default_autonomy']} → {t['max_autonomy']} | {t['blast_radius']} | {t.get('approval', '—')} |")
    for sid, s in servers.items():
        tools = [t for t in cat["tools"] if t["server"] == sid]
        if not tools:
            continue
        L += ["", f"## {s['title']}", "", f"{s['description']} Identity: {s['identity']}.", "",
              f"MCP definitions: [`mcp/{sid}.json`](mcp/{sid}.json)"]
        for t in tools:
            L += ["", f"### `{t['name']}`", "", t["description"] + (" " + t["notes"] if t.get("notes") else ""), "",
                  "| Input | Type | Required |", "| --- | --- | --- |"]
            for k, v in t["inputs"].items():
                typ = v.get("type", "")
                if "enum" in v:
                    typ += " (" + ", ".join(map(str, v["enum"])) + ")"
                L.append(f"| `{k}` | {typ} | {'no' if v.get('optional') else 'yes'} |")
            L += ["", f"Google Cloud: {t['gcp']} · AWS: {t['aws']} · Gates: {', '.join(t['gates'])}"]
    return "\n".join(L) + "\n"


def main():
    check = "--check" in sys.argv
    cat = yaml.safe_load(open(os.path.join(HERE, "catalog.yaml")))
    errs = validate(cat)
    if errs:
        print("Catalogue errors:\n  " + "\n  ".join(errs)); sys.exit(1)
    files = {os.path.join(HERE, "README.md"): readme(cat),
             os.path.join(HERE, "catalog.json"): json.dumps(cat, indent=1) + "\n"}
    for sid, defs in mcp_defs(cat).items():
        files[os.path.join(HERE, "mcp", f"{sid}.json")] = json.dumps({"server": sid, "tools": defs}, indent=1) + "\n"
    stale = []
    for path, content in files.items():
        old = open(path).read() if os.path.exists(path) else None
        if old != content:
            stale.append(os.path.relpath(path, ROOT))
            if not check:
                os.makedirs(os.path.dirname(path), exist_ok=True)
                open(path, "w").write(content)
    if check and stale:
        print("Out of date, run tools/build_catalog.py:\n  " + "\n  ".join(stale)); sys.exit(1)
    print(f"OK: {len(cat['tools'])} tools, {len(cat['servers'])} servers" + ("" if check else f", wrote {len(stale)} file(s)"))


if __name__ == "__main__":
    main()
